private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int octet = bb.get(i);
    if (octet < 0) {
        octet += 256;
    }
    if (octet < 128) {
        sb.append((char) octet);
        return i + 1;
    } else if (octet < 192) {
        // Invalid UTF-8 sequence
        return i;
    } else if (octet < 224) {
        int secondOctet = bb.get(i + 1);
        if (secondOctet < 128 || secondOctet > 191) {
            // Invalid UTF-8 sequence
            return i;
        }
        int codePoint = ((octet & 0x1F) << 6) | (secondOctet & 0x3F);
        if (codePoint > 0xFFFF) {
            // Invalid UTF-8 sequence
            return i;
        }
        sb.append((char) codePoint);
        return i + 2;
    } else if (octet < 240) {
        int secondOctet = bb.get(i + 1);
        int thirdOctet = bb.get(i + 2);
        if (secondOctet < 128 || secondOctet > 191 || thirdOctet < 128 || thirdOctet > 191) {
            // Invalid UTF-8 sequence
            return i;
        }
        int codePoint = ((octet & 0x0F) << 12) | ((secondOctet & 0x3F) << 6) | (thirdOctet & 0x3F);
        if (codePoint > 0x10FFFF) {
            // Invalid UTF-8 sequence
            return i;
        }
        sb.append((char) codePoint);
        return i + 3;
    } else {
        // Invalid UTF-8 sequence
        return i;
    }
