import java.net.URI;
import java.util.ArrayList;
import java.util.List;

public class URIUtils {

    /**
     * Decode the path component of a URI as path segments.
     * @param u the URI. If the path component is an absolute path component then the leading '/' is ignored and is not considered a delimiter of a path segment.
     * @param decode true if the path segments of the path components should be in decoded form.
     * @return the list of path segments.
     */
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return new ArrayList<>();
        }

        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String[] segments = path.split("/");

        for (String segment : segments) {
            if (!segment.isEmpty()) {
                if (decode) {
                    segment = java.net.URLDecoder.decode(segment, "UTF-8");
                }
                pathSegments.add(new PathSegmentImpl(segment));
            }
        }

        return pathSegments;
    }
}

