public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantNameAndTypeInfo constant = (ConstantNameAndTypeInfo) constantPool.get(i);
        if (constant.getName().equals(name) && constant.getDescriptor().equals(descriptor)) {
            return i; // Return the index of the existing item
        }
    }

    // If no similar item is found, add a new one to the constant pool
    ConstantNameAndTypeInfo newConstant = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(newConstant);
    return constantPool.size() - 1; // Return the index of the newly added item
}

private String unescapeId(String input) {
