            switch (c) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                default:
                    result.append(c);
                    break;
            }
            inEscape = false;
        } else if (c == '\\') {
            inEscape = true;
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

