import javax.swing.JTable;
import javax.swing.JScrollPane;

public class TableUtils {

    /**
     * Selects a specified row in the specified JTable and scrolls the specified JScrollpane to the newly selected row.
     * More importantly, the call to repaint() is delayed long enough to have the table properly paint the newly selected row,
     * which may be off-screen.
     *
     * @param row    the index of the row to select
     * @param table  the JTable to select the row in
     * @param pane   the JScrollpane containing the JTable
     */
    public static void selectRow(int row, JTable table, JScrollPane pane) {
        // Select the specified row
        table.setRowSelectionInterval(row, row);

        // Scroll the JScrollPane to the newly selected row
        pane.getViewport().setViewPosition(new java.awt.Point(0, table.getRowHeight() * row));

        // Delay the repaint to ensure the newly selected row is properly painted
        try {
            Thread.sleep(100); // Adjust the delay as needed
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        // Repaint the table
        table.repaint();
    }
}

public ByteVector putInt(final int intValue) {
    // Ensure there is enough space in the byte vector to store the int
    if (size + 4 > capacity) {
        // Enlarge the byte vector
        capacity = Math.max(capacity * 2, size + 4);
        byte[] newBuffer = new byte[capacity];
        System.arraycopy(buffer, 0, newBuffer, 0, size);
        buffer = newBuffer;
    }

    // Convert the int to a byte array and copy it into the byte vector
    byte[] intBytes = new byte[4];
    intBytes[0] = (byte) (intValue >> 24);
    intBytes[1] = (byte) (intValue >> 16);
    intBytes[2] = (byte) (intValue >> 8);
    intBytes[3] = (byte) intValue;

    System.arraycopy(intBytes, 0, buffer, size, 4);
    size += 4;

    return this;
}

