    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex.equals(otherVertex)) {
                continue;
            }
            if (!graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }
    return true;
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class KeyLowerBoundCalculator {

    /** 
     * Finds a maximum lower bound for every key.
     * @param keys list of keys.
     * @return the computed key lower bounds.
     */
    private List<Integer> computeLowerBounds(List<K> keys) {
        if (keys == null || keys.isEmpty()) {
            return Collections.emptyList();
        }

        List<Integer> lowerBounds = new ArrayList<>();
        Collections.sort(keys);

        for (int i = 0; i < keys.size(); i++) {
            if (i == 0) {
                lowerBounds.add(keys.get(i));
            } else {
                lowerBounds.add(Math.max(lowerBounds.get(i - 1), keys.get(i)));
            }
        }

        return lowerBounds;
    }
}

