public static String applyRelativePath(String path, String relativePath) {
    // Split the path into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Start with the base path components
    List<String> result = new ArrayList<>(Arrays.asList(pathComponents));

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (".".equals(component)) {
            // Ignore the current directory
            continue;
        } else if ("..".equals(component)) {
            // Go up one directory
            if (!result.isEmpty()) {
                result.remove(result.size() - 1);
            }
        } else {
            // Add the new component
            result.add(component);
        }
    }

    // Join the components back into a single path
    return String.join("/", result);
}

